begin;
create table if not exists public.portfolio_risk_matrix_v42(id bigserial primary key,matrix_date date not null,portfolio_id_a uuid not null references public.enterprise_portfolios_v40(id) on delete cascade,portfolio_id_b uuid not null references public.enterprise_portfolios_v40(id) on delete cascade,correlation numeric not null default 0,overlap_score numeric not null default 0,joint_stress_loss_pct numeric not null default 0,risk_status text not null,diagnostics jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create unique index if not exists portfolio_risk_matrix_v42_uidx on public.portfolio_risk_matrix_v42(matrix_date,portfolio_id_a,portfolio_id_b);
create table if not exists public.strategy_correlation_v42(id bigserial primary key,correlation_date date not null,strategy_id_a uuid not null references public.enterprise_strategies_v40(id) on delete cascade,strategy_id_b uuid not null references public.enterprise_strategies_v40(id) on delete cascade,correlation numeric not null default 0,diversification_score numeric not null default 0,risk_status text not null,diagnostics jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create unique index if not exists strategy_correlation_v42_uidx on public.strategy_correlation_v42(correlation_date,strategy_id_a,strategy_id_b);
create table if not exists public.scenario_definitions_v42(id bigserial primary key,scenario_key text not null unique,scenario_name text not null,equity_shock_pct numeric not null default 0,volatility_multiplier numeric not null default 1,correlation_shift numeric not null default 0,enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.scenario_results_v42(id bigserial primary key,scenario_date date not null,scenario_id bigint not null references public.scenario_definitions_v42(id) on delete cascade,portfolio_id uuid not null references public.enterprise_portfolios_v40(id) on delete cascade,estimated_loss_pct numeric not null default 0,post_scenario_equity numeric not null default 0,risk_status text not null,diagnostics jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create unique index if not exists scenario_results_v42_uidx on public.scenario_results_v42(scenario_date,scenario_id,portfolio_id);
create table if not exists public.monte_carlo_runs_v42(id uuid primary key default gen_random_uuid(),run_date date not null,portfolio_id uuid not null references public.enterprise_portfolios_v40(id) on delete cascade,paths integer not null,horizon_days integer not null,initial_equity numeric not null default 0,percentile_5_equity numeric not null default 0,median_equity numeric not null default 0,percentile_95_equity numeric not null default 0,probability_of_loss numeric not null default 0,probability_of_breach numeric not null default 0,expected_shortfall_pct numeric not null default 0,status text not null,diagnostics jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create unique index if not exists monte_carlo_runs_v42_uidx on public.monte_carlo_runs_v42(run_date,portfolio_id);
create table if not exists public.dynamic_position_sizing_v42(id bigserial primary key,sizing_date date not null,portfolio_id uuid not null references public.enterprise_portfolios_v40(id) on delete cascade,symbol text not null,base_weight numeric not null default 0,regime_multiplier numeric not null default 1,risk_budget_multiplier numeric not null default 1,final_target_weight numeric not null default 0,action text not null,rationale text not null,created_at timestamptz not null default now());
create unique index if not exists dynamic_position_sizing_v42_uidx on public.dynamic_position_sizing_v42(sizing_date,portfolio_id,symbol);
create table if not exists public.rebalance_proposals_v42(id uuid primary key default gen_random_uuid(),proposal_date date not null,portfolio_id uuid not null references public.enterprise_portfolios_v40(id) on delete cascade,proposal_status text not null default 'PROPOSED',gross_turnover_pct numeric not null default 0,estimated_cost numeric not null default 0,target_cash_pct numeric not null default 0,risk_before numeric not null default 0,risk_after numeric not null default 0,requires_approval boolean not null default true,paper_only boolean not null default true,summary text not null,blockers jsonb not null default '[]'::jsonb,created_at timestamptz not null default now());
create unique index if not exists rebalance_proposals_v42_uidx on public.rebalance_proposals_v42(proposal_date,portfolio_id);
create table if not exists public.rebalance_items_v42(id bigserial primary key,proposal_id uuid not null references public.rebalance_proposals_v42(id) on delete cascade,symbol text not null,current_weight numeric not null default 0,target_weight numeric not null default 0,delta_weight numeric not null default 0,action text not null,estimated_trade_value numeric not null default 0,rationale text not null,created_at timestamptz not null default now());
create unique index if not exists rebalance_items_v42_uidx on public.rebalance_items_v42(proposal_id,symbol);
create table if not exists public.adaptive_allocation_status_v42(id bigserial primary key,status_date date not null unique,overall_status text not null,portfolios_processed integer not null default 0,strategies_processed integer not null default 0,scenarios_run integer not null default 0,monte_carlo_runs integer not null default 0,proposals_generated integer not null default 0,live_trading_enabled boolean not null default false,blockers jsonb not null default '[]'::jsonb,summary text not null,created_at timestamptz not null default now());
insert into public.scenario_definitions_v42(scenario_key,scenario_name,equity_shock_pct,volatility_multiplier,correlation_shift) values('market-correction','Market Correction',-10,1.5,0.10),('bear-market','Bear Market',-20,2.0,0.20),('liquidity-shock','Liquidity Shock',-8,1.8,0.15),('correlation-spike','Correlation Spike',-12,1.6,0.35) on conflict(scenario_key) do update set scenario_name=excluded.scenario_name,equity_shock_pct=excluded.equity_shock_pct,volatility_multiplier=excluded.volatility_multiplier,correlation_shift=excluded.correlation_shift,updated_at=now();
alter table public.portfolio_risk_matrix_v42 enable row level security; drop policy if exists "enterprise42 read portfolio matrix" on public.portfolio_risk_matrix_v42; create policy "enterprise42 read portfolio matrix" on public.portfolio_risk_matrix_v42 for select to anon, authenticated using (true);
alter table public.strategy_correlation_v42 enable row level security; drop policy if exists "enterprise42 read strategy correlation" on public.strategy_correlation_v42; create policy "enterprise42 read strategy correlation" on public.strategy_correlation_v42 for select to anon, authenticated using (true);
alter table public.scenario_definitions_v42 enable row level security; drop policy if exists "enterprise42 read scenarios" on public.scenario_definitions_v42; create policy "enterprise42 read scenarios" on public.scenario_definitions_v42 for select to anon, authenticated using (true);
alter table public.scenario_results_v42 enable row level security; drop policy if exists "enterprise42 read scenario results" on public.scenario_results_v42; create policy "enterprise42 read scenario results" on public.scenario_results_v42 for select to anon, authenticated using (true);
alter table public.monte_carlo_runs_v42 enable row level security; drop policy if exists "enterprise42 read monte carlo" on public.monte_carlo_runs_v42; create policy "enterprise42 read monte carlo" on public.monte_carlo_runs_v42 for select to anon, authenticated using (true);
alter table public.dynamic_position_sizing_v42 enable row level security; drop policy if exists "enterprise42 read sizing" on public.dynamic_position_sizing_v42; create policy "enterprise42 read sizing" on public.dynamic_position_sizing_v42 for select to anon, authenticated using (true);
alter table public.rebalance_proposals_v42 enable row level security; drop policy if exists "enterprise42 read proposals" on public.rebalance_proposals_v42; create policy "enterprise42 read proposals" on public.rebalance_proposals_v42 for select to anon, authenticated using (true);
alter table public.rebalance_items_v42 enable row level security; drop policy if exists "enterprise42 read items" on public.rebalance_items_v42; create policy "enterprise42 read items" on public.rebalance_items_v42 for select to anon, authenticated using (true);
alter table public.adaptive_allocation_status_v42 enable row level security; drop policy if exists "enterprise42 read status" on public.adaptive_allocation_status_v42; create policy "enterprise42 read status" on public.adaptive_allocation_status_v42 for select to anon, authenticated using (true);
notify pgrst,'reload schema'; commit; select 'GPT Quant Enterprise 4.2 Stable setup complete' as result;
